describe('Password Requirements Tooltip', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display tooltip with password requirements when user hovers over password field', () => {
    // Verify password field is visible
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Hover over password field to trigger tooltip
    cy.get('[data-testid="password-input"]').trigger('mouseenter');

    // Verify tooltip appears
    cy.get('[data-testid="password-tooltip"]').should('be.visible');

    // Verify tooltip contains required information
    cy.get('[data-testid="password-tooltip"]').should('contain', 'At least 8 characters');
    cy.get('[data-testid="password-tooltip"]').should('contain', 'One uppercase letter');
    cy.get('[data-testid="password-tooltip"]').should('contain', 'One lowercase letter');
    cy.get('[data-testid="password-tooltip"]').should('contain', 'One number');

    // Verify tooltip has correct styling
    cy.get('[data-testid="password-tooltip"]').should('have.css', 'opacity', '1');

    // Verify tooltip disappears when mouse leaves
    cy.get('[data-testid="password-input"]').trigger('mouseleave');
    cy.get('[data-testid="password-tooltip"]').should('not.exist');
  });

  it('should not display tooltip when password field is not focused or hovered', () => {
    // Verify tooltip does not exist initially
    cy.get('[data-testid="password-tooltip"]').should('not.exist');

    // Click on another element to ensure no focus on password field
    cy.get('[data-testid="username-input"]').click();

    // Verify tooltip still does not appear
    cy.get('[data-testid="password-tooltip"]').should('not.exist');

    // Verify tooltip does not appear when clicking on password field without hovering
    cy.get('[data-testid="password-input"]').click();
    cy.get('[data-testid="password-tooltip"]').should('not.exist');

    // Verify tooltip does not appear when clicking on submit button
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="password-tooltip"]').should('not.exist');
  });
});
